/* D117：甲方变更申请。仅浏览器内存演示；刷新恢复样例，不写主文件事实。 */
const cgStyle='width:100%;padding:10px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--fg);font:inherit';
const cgOriginal={id:'IN-2028',title:'账单导出支持 CSV',project:'p1',requirement:'R-12',version:3,expected:'2026-10-23',raw:'请让账单支持 CSV 导出，保留账单日期、金额和客户名称，方便财务对账。',attachments:['账单导出字段说明.pdf'],history:[[1,'提交 CSV 导出的字段与格式约定'],[2,'明确字段顺序与金额格式'],[3,'CSV 文件名带日期；来自变更 IN-2033']]};
const cgChanges={
 'IN-2042':{id:'IN-2042',kind:'CHANGE',change_of_intake_id:'IN-2028',target_requirement_id:'R-12',title:'导出增加 Excel 格式并支持按部门筛选',why:'财务需要直接使用 Excel，并按部门分别对账。',date:'2026-10-23',attachments:['部门筛选说明.pdf'],state:'waiting',revision:1,base:3,approval:null,days:4,expected:'2026-10-27',cost:38,price:'1200',breached:true,reason:'',criteria:[['新增','支持导出 Excel 文件，列顺序与 CSV 一致'],['新增','可按部门筛选后导出该部门账单'],['替换','仅 CSV 导出 → 可选择 CSV 或 Excel 导出']],impacts:[['BIL-142','基线过期'],['待创建','Excel 格式导出'],['待创建','按部门筛选导出']]},
 'IN-2033':{id:'IN-2033',kind:'CHANGE',change_of_intake_id:'IN-2028',target_requirement_id:'R-12',title:'CSV 文件名带日期',why:'方便你区分每日账单文件。',date:'',attachments:[],state:'accepted',revision:1,base:2,version:3,approval:null,days:0,expected:'2026-10-23',cost:0,price:'',breached:false,reason:'',criteria:[['替换','CSV 文件名增加导出日期']],impacts:[],notice:'容差内，无需你确认；工期不变，费用不变。'}
};
let cgPortalState='已转化';
let cgListPreview='正常';
let cgIdentity='human';
let cgScope=true;
let cgException=false;
let cgCurrent='IN-2042';
let cgSerial=2043;
function cgEsc(cgValue){return String(cgValue==null?'':cgValue).replace(/[&<>"']/g,cgChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[cgChar]));}
function cgBtn(cgText,cgCall,cgKind='',cgDisabled=false,cgHint=''){return `<span class="stack" style="gap:4px;align-items:flex-start"><button type="button" class="btn ${cgKind}" onclick="${cgEsc(cgCall)}" ${cgDisabled?'disabled':''}>${cgText}</button>${cgDisabled?`<span class="muted xs">${cgEsc(cgHint)}</span>`:''}</span>`;}
function cgKV(cgRows){return `<dl class="kv">${cgRows.map(cgRow=>`<dt>${cgRow[0]}</dt><dd>${cgRow[1]}</dd>`).join('')}</dl>`;}
function cgBadge(cgChange){const cgText=cgChange.state==='accepted'?`已接受（需求 v${cgChange.version}）`:cgChange.state==='declined'?`未接受（${cgEsc(cgChange.reason)}）`:cgChange.state==='waiting'?'待你确认':'评估中';return `<span class="badge ${cgChange.state==='accepted'?'b-ok':cgChange.state==='declined'?'b-danger':cgChange.state==='waiting'?'b-warn':'b-info'}">${cgText}</span>`;}
function cgPortal(cgBody){return `<div style="max-width:1000px;margin:auto"><div class="row wrap" style="padding:20px 0"><div style="background:#0f766e;color:white;padding:10px 16px;border-radius:10px;font-weight:700">N</div><div><b style="font-family:var(--font-head);font-size:18px">${cgEsc(TEAM.name)} · 需求门户</b><div class="muted small">你好，${cgEsc(PEOPLE.lee.n)}（甲方联系人）· 品牌来自团队配置</div></div><a class="btn sm" style="margin-left:auto" href="#/overview">${I('arrow-left')}返回团队控制台（原型导航）</a></div><div class="tabs wrap">${[['我的需求','portal'],['提交新需求','portal-submit'],['待回答 · 1','portal-clarify'],['待验收 · 1','portal-accept']].map((cgTab,cgIndex)=>`<button class="${cgIndex?'':'on'}" onclick="go('${cgTab[1]}')">${cgTab[0]}</button>`).join('')}</div><div class="stack">${cgBody}</div></div>`;}
function cgMissing(cgPortalSide){const cgBody=card('未找到记录','<div class="empty">请检查来件编号。</div><a class="btn" href="#/portal-intake/IN-2028">返回示例需求</a>');return cgPortalSide?cgPortal(cgBody):cgBody;}
function cgOriginalId(cgId){return !cgId||cgId==='IN-2028';}
function cgChips(cgLabels,cgSelected,cgCall){return `<div class="row wrap"><span class="small muted">状态预览</span>${cgLabels.map(cgLabel=>`<button type="button" class="chip ${cgLabel===cgSelected?'on':''}" aria-pressed="${cgLabel===cgSelected}" onclick="${cgCall}('${cgLabel}')">${cgLabel}</button>`).join('')}</div>`;}
function cgPreviewPortal(cgValue){cgPortalState=cgValue;route();}
function cgPreviewList(cgValue){cgListPreview=cgValue;route();}
PAGES['portal-intake']=(cgId)=>{
 if(!cgOriginalId(cgId))return cgMissing(true);
 const cgConverted=cgPortalState==='已转化',cgRejected=cgPortalState==='已拒绝';
 return cgPortal(`<div class="row wrap"><h1 class="grow">${cgOriginal.title}</h1><span class="badge ${cgRejected?'b-danger':cgConverted?'b-ok':'b-info'}">${cgRejected?'已拒绝':cgConverted?'已转为需求':'评估中'}</span></div>${cgChips(['评估中','已转化','已拒绝'],cgPortalState,'cgPreviewPortal')}
 ${card('里程碑',`<div class="milestones">${['已接收','澄清中','进行中','待验收','已交付'].map((cgName,cgIndex)=>`<div style="${cgIndex===(cgConverted?2:0)?'font-weight:700;color:var(--primary)':''}">${cgName}</div>`).join('')}</div>${cgKV([['提交编号','IN-2028'],['项目','账单中心'],['当前阶段',cgRejected?'已拒绝 · 当前交付范围不包含此需求':cgConverted?'进行中':'团队评估中'],['预计日期',cgOriginal.expected+'（仅已接受的变更生效）']])}`)}
 ${card('原文与附件 · 只读',`<p style="white-space:pre-wrap">${cgEsc(cgOriginal.raw)}</p><div class="row">${I('paperclip')}${cgOriginal.attachments.map(cgEsc).join('、')}</div><div class="note info">已提交的需求不能直接修改，变更会形成新版本并保留历史。</div>${(cgOriginal.supplements||[]).map(cgText=>`<p class="small">补充说明：${cgEsc(cgText)}</p>`).join('')}${cgConverted?`<p class="muted small">需求已转入开发，不再提供补充说明；请通过申请变更提出新的要求。</p>${cgBtn('申请变更',"go('portal-change/IN-2028')",'primary')}`:cgRejected?'<p class="muted small">来件已拒绝，不能补充说明或申请变更。</p>':cgBtn('补充说明','cgSupplement()','primary')}`)}
 ${card('需求版本历史',cgConverted?`<div class="stack">${cgOriginal.history.map(cgVersion=>`<div><b>v${cgVersion[0]}</b> ${cgEsc(cgVersion[1])}</div>`).join('')}</div>`:'<div class="empty">尚未转为需求，没有需求版本。</div>')}
 ${card('变更申请列表',cgChips(['正常','异常','空'],cgListPreview,'cgPreviewList')+(cgListPreview==='异常'?`<div class="note danger">变更列表暂时无法加载，原需求未受影响。</div>${cgBtn('重试',"cgPreviewList('正常')")}`:cgListPreview==='空'?'<div class="empty">暂无变更申请；你可以通过申请变更提出新的要求。</div>':cgConverted?Object.values(cgChanges).map(cgChange=>`<div class="inbox-item"><div class="stack"><div class="row wrap"><a href="#/portal-change-approval/${cgChange.id}">${cgChange.id} · ${cgEsc(cgChange.title)}</a>${cgBadge(cgChange)}</div>${cgChange.notice?`<p class="small">${cgEsc(cgChange.notice)}</p>`:''}${cgChange.approval?.result==='rejected'&&cgChange.state!=='declined'?'<p class="small">你已不同意本次方案，团队正在沟通调整，原需求保持不变。</p>':''}</div></div>`).join(''):'<div class="empty">需求未转化，暂无变更申请。</div>'))}`);
};
function cgSupplement(){if(cgPortalState!=='评估中')return toast('只有转入开发前可以补充说明');openModal(`<div class="stack" style="padding:24px"><h3>补充说明</h3><label class="stack">补充内容<textarea id="cgSupplement" style="${cgStyle}" maxlength="20000" rows="4"></textarea></label><p class="muted small">补充说明将作为独立记录保留，不覆盖已提交原文。</p>${cgBtn('提交补充','cgSaveSupplement()','primary')}${cgBtn('取消','closeModal()')}</div>`);}
function cgSaveSupplement(){const cgText=document.getElementById('cgSupplement').value.trim();if(!cgText)return toast('请填写补充内容');cgOriginal.supplements=(cgOriginal.supplements||[]).concat(cgText);closeModal();toast('补充说明已记录（浏览器内演示）');}
PAGES['portal-change']=(cgId)=>{
 if(!cgOriginalId(cgId))return cgMissing(true);
 if(cgPortalState!=='已转化')return cgPortal(card('不能申请变更','只有已转为需求的来件可以申请变更。<a href="#/portal-intake/IN-2028">返回需求详情</a>'));
 return cgPortal(`<h1>申请变更</h1><form id="cgChangeForm" class="stack" onsubmit="cgSubmit(event)">
 ${card('原需求',cgKV([['提交编号','IN-2028'],['标题',cgOriginal.title],['需求版本',`v${cgOriginal.version}`]])+'<p class="muted small">原文只读，新申请不会覆盖原需求。</p>')}
 ${card('变更内容',`<div class="stack"><label class="stack">要改什么（必填，1..20000 字）<textarea name="content" style="${cgStyle}" rows="5" required minlength="1" maxlength="20000"></textarea></label><label class="stack">为什么（必填）<textarea name="why" style="${cgStyle}" rows="3" required></textarea></label></div>`)}
 ${card('期望与附件',`<div class="stack"><label class="stack">期望日期（可选）<input name="date" type="date" style="${cgStyle}"></label><label class="stack">附件（最多 10 个）<input name="files" type="file" multiple onchange="cgFileLimit(this)"></label><p class="muted small">期望日期供团队评估，不代表已承诺的交付日期。</p></div>`)}
 ${card('提交前确认',`<div class="note info">团队评估后会告诉你对工期和费用的影响；超出原约定时会先请你确认。</div><div id="cgFormError" role="alert" class="note danger" hidden></div><div class="row wrap"><button type="submit" class="btn primary">提交变更申请</button><a class="btn ghost" href="#/portal-intake/IN-2028">取消</a></div>`)}</form>`);
};
function cgFileLimit(cgInput){cgInput.setCustomValidity(cgInput.files.length>10?'附件不能超过 10 个':'');if(cgInput.files.length>10)cgInput.reportValidity();}
function cgSubmit(cgEvent){cgEvent.preventDefault();const cgForm=cgEvent.target,cgContent=cgForm.elements.content.value.trim(),cgWhy=cgForm.elements.why.value.trim();if(cgPortalState!=='已转化'||!cgContent||Array.from(cgContent).length>20000||!cgWhy||cgForm.elements.files.files.length>10){const cgError=document.getElementById('cgFormError');cgError.hidden=false;cgError.textContent='请检查必填内容、字数、附件数量以及原需求状态。';return;}const cgId='IN-'+cgSerial++;cgChanges[cgId]={id:cgId,kind:'CHANGE',change_of_intake_id:'IN-2028',target_requirement_id:'R-12',title:cgContent,why:cgWhy,date:cgForm.elements.date.value,attachments:Array.from(cgForm.elements.files.files,cgFile=>cgFile.name),state:'evaluating',revision:1,base:cgOriginal.version,approval:null,days:null,expected:'',cost:null,price:'',breached:null,criteria:[],impacts:[]};toast('变更申请已提交，等待团队评估（浏览器内演示）');go('portal-intake/IN-2028');}
function cgImpact(cgChange,cgTeam=false){return `<div class="stack">${cgChange.criteria.map(cgCriterion=>`<div class="row wrap"><span class="badge ${cgCriterion[0]==='新增'?'b-ok':cgCriterion[0]==='退役'?'b-danger':'b-info'}">${cgTeam?cgCriterion[0]:cgCriterion[0]==='替换'?'调整':cgCriterion[0]==='退役'?'不再需要':'新增'}</span><span>${cgEsc(cgCriterion[1])}</span></div>`).join('')||'<div class="empty">团队尚未完成影响评估。</div>'}${!cgTeam&&cgChange.criteria.length?'<p class="muted small">不再需要：无单独移除的内容；CSV 导出能力保留。</p>':''}</div>`;}
function cgPrice(cgChange){return cgChange.price===''?'未填写费用变化':`+¥${Number(cgChange.price).toLocaleString('zh-CN')}`;}
function cgApprovalText(cgChange){return cgChange.approval?`${cgChange.approval.result==='approved'?'已同意':'不同意'} · ${cgEsc(cgChange.approval.time)}${cgChange.approval.source==='offline'?' · 由团队记录':''}${cgChange.approval.comment?`<p>${cgEsc(cgChange.approval.comment)}</p>`:''}`:cgChange.state==='waiting'?'待你确认':cgChange.breached===false?'容差内，不需甲方确认':'尚未提交确认';}
PAGES['portal-change-approval']=(cgId)=>{
 const cgChange=cgChanges[cgId||'IN-2042'];if(!cgChange)return cgMissing(true);
 const cgWaiting=cgChange.state==='waiting'&&!cgChange.approval;
 return cgPortal(`<div class="row wrap"><h1 class="grow">变更影响确认</h1>${cgBadge(cgChange)}</div><a href="#/portal-intake/IN-2028">返回原需求</a>
 ${card('变更内容',`<b>${cgEsc(cgChange.title)}</b><p>${cgEsc(cgChange.why)}</p>${cgImpact(cgChange)}`)}
 ${card('对交付的影响',cgChange.days===null?'<div class="empty">团队评估中，工期与费用尚未确定。</div>':cgKV([['已完成的部分',cgChange.id==='IN-2042'?'1 项已完成的内容需要按新要求调整':'按原计划交付'],['工期变化',`+${cgChange.days} 天`],['新的预计日期',cgEsc(cgChange.expected)],...(cgChange.price!==''?[['费用变化',cgPrice(cgChange)]]:[])])+`<div class="note info">同意后按新的工期与费用执行；不同意时团队会与你沟通调整方案或保持原需求。</div>`)}
 ${card('你的决定',cgWaiting?`<div class="stack"><label class="row"><input id="cgRead" type="checkbox" onchange="document.getElementById('cgAgree').disabled=!this.checked;document.getElementById('cgAgreeHint').hidden=this.checked">我已阅读上述影响</label><button id="cgAgree" style="align-self:flex-start" class="btn primary" disabled onclick="cgDecide('approved')">同意并继续</button><p id="cgAgreeHint" class="muted small">请先勾选「我已阅读上述影响」。</p><label class="stack">不同意的理由（必填，10..2000 字）<textarea id="cgDisagree" style="${cgStyle}" rows="3" minlength="10" maxlength="2000" oninput="cgReasonReady(this)"></textarea></label><button id="cgRejectApproval" style="align-self:flex-start" class="btn" disabled onclick="cgDecide('rejected')">不同意</button><p id="cgRejectHint" class="muted small">请填写 10..2000 字理由。</p><div class="note info">不同意后，原需求保持不变；团队会与你沟通，调整方案后再请你确认，或撤回这次变更。</div><div id="cgApprovalError" class="note danger" role="alert" hidden></div></div>`:`<div class="stack"><b>${cgApprovalText(cgChange)}</b>${cgChange.state==='accepted'?`<p>已接受（需求 v${cgChange.version}）</p>`:''}${cgChange.state==='declined'?`<p>未接受：${cgEsc(cgChange.reason)}</p>`:''}<p class="muted small">${cgChange.approval?'结果与时间只读；本次决定不自动修改需求。':cgChange.notice?cgEsc(cgChange.notice):'当前没有待你确认的请求。'}</p></div>`)}${cgChange.state==='waiting'?'<p class="muted small">7 天后提醒你，14 天后提醒团队；不会自动替你决定。</p>':''}`);
};
function cgReasonReady(cgInput){const cgLength=Array.from(cgInput.value.trim()).length,cgReady=cgLength>=10&&cgLength<=2000;document.getElementById('cgRejectApproval').disabled=!cgReady;document.getElementById('cgRejectHint').hidden=cgReady;}
function cgDecide(cgResult){const cgId=location.hash.split('/')[2]||'IN-2042',cgChange=cgChanges[cgId];if(!cgChange||cgChange.state!=='waiting'||cgChange.approval)return toast('确认请求已失效');if(cgResult==='approved'){if(!document.getElementById('cgRead').checked)return toast('请先阅读上述影响');cgSaveDecision(cgChange,'approved','');}else{const cgComment=document.getElementById('cgDisagree').value.trim();if(Array.from(cgComment).length<10||Array.from(cgComment).length>2000)return toast('理由须为 10..2000 字');cgSaveDecision(cgChanges[cgId],'rejected',cgComment);}}
function cgSaveDecision(cgChange,cgResult,cgComment,cgSource='portal',cgEvidence=[]){if(cgChange.state!=='waiting'||cgChange.approval)return toast('确认请求已失效');cgChange.approval={result:cgResult,comment:cgComment,time:new Date().toLocaleString('zh-CN',{hour12:false}),source:cgSource,revision:cgChange.revision,evidence:cgEvidence};cgChange.state='evaluating';closeModal();route();toast(cgResult==='approved'?'你已同意，等待团队转换新需求版本':'你已不同意，团队将与你沟通');}
function cgTeamState(cgChange){return cgChange.state==='waiting'?'待甲方确认':cgChange.approval?.result==='approved'?'甲方已同意':cgChange.approval?.result==='rejected'?'甲方不同意':cgChange.breached===false?'容差内':'评估中';}
function cgPreviewTeam(cgValue){const cgChange=cgChanges[cgCurrent];if(cgCurrent!=='IN-2042')return toast('此预览仅适用于 IN-2042');cgChange.state=cgValue==='待甲方确认'?'waiting':'evaluating';cgChange.breached=cgValue!=='容差内';cgChange.days=cgValue==='容差内'?0:4;cgChange.expected=cgValue==='容差内'?'2026-10-23':'2026-10-27';cgChange.approval=['甲方已同意','甲方不同意'].includes(cgValue)?{result:cgValue==='甲方已同意'?'approved':'rejected',revision:cgChange.revision,time:'2026-10-12 10:30',source:'portal',comment:cgValue==='甲方不同意'?'新增费用超出预算，请沟通简化方案。':''}:null;route();}
function cgAllowed(){return cgIdentity==='human'&&cgScope;}
function cgReady(cgChange){return cgChange.criteria.length>0&&cgChange.days!==null&&cgChange.breached!==null;}
function cgCanConvert(cgChange){return cgAllowed()&&cgReady(cgChange)&&cgChange.state==='evaluating'&&cgChange.base===cgOriginal.version&&!cgException&&(cgChange.breached===false||(cgChange.approval?.result==='approved'&&cgChange.approval.revision===cgChange.revision));}
PAGES['change-intake']=(cgId)=>{
 const cgChange=cgChanges[cgId||'IN-2042'];if(!cgChange)return cgMissing(false);cgCurrent=cgChange.id;
 const cgHuman=cgAllowed(),cgLocked=cgChange.state==='waiting'||['accepted','declined'].includes(cgChange.state),cgCanSubmit=cgHuman&&cgReady(cgChange)&&cgChange.breached===true&&cgChange.state==='evaluating'&&!cgChange.approval&&cgChange.base===cgOriginal.version;
 const cgAuthHint=cgIdentity!=='human'?'仅人类可执行；协调员 Agent 只能起草影响评估':!cgScope?'你缺少 scope_change 权限':'';
 return head('变更来件',`${cgChange.id} · ${cgEsc(cgChange.title)}`,'所有操作仅修改浏览器内存，刷新恢复样例。')+`<div class="stack"><div class="row wrap"><span class="muted small">身份切换</span>${cgBtn('人类负责人',"cgIdentity='human';route()",cgIdentity==='human'?'primary sm':'sm')}${cgBtn('协调员 Agent',"cgIdentity='agent';route()",cgIdentity==='agent'?'primary sm':'sm')}<label class="row"><input type="checkbox" ${cgScope?'checked':''} onchange="cgScope=this.checked;route()">具备 <span class="mono">scope_change</span></label><label class="row"><input type="checkbox" ${cgException?'checked':''} onchange="cgException=this.checked;route()">存在未关闭的容差例外</label></div>${cgChange.id==='IN-2042'?cgChips(['评估中','待甲方确认','甲方已同意','甲方不同意','容差内'],cgTeamState(cgChange),'cgPreviewTeam'):''}
 <div class="grid g12"><div class="c4">${card('原需求与版本',cgKV([['原来件','<a href="#/portal-intake/IN-2028">IN-2028 · 账单导出支持 CSV</a>'],['目标需求',`R-12 v${cgOriginal.version}`],['评估基于',`v${cgChange.base} · 评估修订 ${cgChange.revision}`],['项目','<a href="#/project/p1">账单中心 · p1</a>'],['来件类型','甲方变更']]))}</div><div class="c8">${card('甲方变更原文 · 只读',`<p style="white-space:pre-wrap;overflow-wrap:anywhere">${cgEsc(cgChange.title)}</p>${cgKV([['为什么',cgEsc(cgChange.why)],['期望日期',cgEsc(cgChange.date)||'未填写'],['附件',cgChange.attachments.map(cgEsc).join('、')||'无']])}`)}</div></div>
 ${card('影响评估',`<div class="note warn">主管 Agent 起草 · 需人确认。${cgLocked?'确认请求等待期间与终态不能修改影响评估。':'提交前由你核对影响与对外费用。'}</div><div class="grid g12"><div class="c8"><h3>验收标准差异 · 新增 / 退役 / 替换</h3>${cgImpact(cgChange,true)}<p class="muted small">本次无单独退役标准；替换后保留旧版本历史。</p><h3>受影响工作项</h3>${cgChange.impacts.map(cgItem=>`<p><span class="mono">${cgEsc(cgItem[0])}</span> · ${cgEsc(cgItem[1])}</p>`).join('')||'<p class="muted">暂无影响项。</p>'}${cgChange.id==='IN-2042'?'<p class="small">新增 2 项；BIL-142 在新版本生效后标记基线过期。</p>':''}</div><div class="c4">${cgKV([['工期变化',cgChange.days===null?'待评估':`+${cgChange.days} 天`],['新的预计日期',cgEsc(cgChange.expected)||'待评估'],['内部成本',cgChange.cost===null?'待评估':`+$${cgChange.cost} <span class="badge b-stale">仅团队可见</span>`]])}<label class="stack">给甲方的费用变化（人民币，可空）<input id="cgPrice" type="number" min="0" step="0.01" style="${cgStyle}" value="${cgEsc(cgChange.price)}" ${cgLocked||!cgHuman?'disabled':''} onchange="cgSetPrice(this)"></label><p class="muted small">${!cgHuman?cgAuthHint:cgLocked?'等待确认时冻结同版评估与费用。':'费用由人类填写，不从内部成本计算。'}留空时不向甲方展示费用。</p></div></div><div class="note ${cgChange.breached?'warn':'info'}">容差检查：${cgChange.breached===null?'待评估':cgChange.breached?'时间越界 → 需甲方确认；成本、范围未越界。':'时间、成本、范围均未越界 → 不需甲方确认，转换后告知结果与影响。'}</div>`)}
 ${card('甲方确认状态',`<div class="stack"><b>${cgApprovalText(cgChange)}</b><p class="small">${cgChange.approval?`确认对应评估修订 ${cgChange.approval.revision}`:'尚无确认记录'} · 当前来件：${cgChange.state==='waiting'?'待甲方确认':cgChange.state==='accepted'?'已转为需求':cgChange.state==='declined'?'已拒绝':'已分诊'}</p>${cgChange.approval?.source==='offline'?`<p>书面证据：${cgChange.approval.evidence.map(cgEsc).join('、')} · 由团队记录</p>`:''}<p class="muted small">7 天提醒甲方、14 天提醒团队；不会自动决定。等待期间不可产生新的评估修订，修改前先撤回请求。</p></div>`)}
 ${card('处理操作',`<div class="stack"><div class="row wrap">${cgBtn('提交甲方确认','cgSubmitApproval()','primary',!cgCanSubmit,cgAuthHint||(!cgReady(cgChange)?'影响评估未完成':cgChange.breached===false?'容差内无需甲方确认':cgChange.base!==cgOriginal.version?'评估版本已过期':'只在评估中且没有决定时可提交'))}${cgBtn('撤回确认请求',"cgTeamDanger('withdraw')",'danger',!cgHuman||cgChange.state!=='waiting',cgAuthHint||'仅待甲方确认时可撤回')}${cgBtn('记录线下同意','cgOffline()','',!cgHuman||cgChange.state!=='waiting',cgAuthHint||'仅待甲方确认时可登记书面同意')}${cgBtn('转为需求 v'+(cgChange.base+1),"cgTeamDanger('convert')",'danger',!cgCanConvert(cgChange),cgAuthHint||(!cgReady(cgChange)?'影响评估尚未完成':cgException?'容差例外尚未关闭，不能调整基线':cgChange.base!==cgOriginal.version?'需求版本已变化，请重新评估':cgChange.state==='waiting'||cgChange.breached&&cgChange.approval?.result!=='approved'?'须先取得甲方对同版评估的同意':'仅评估中且确认有效时可转换'))}${cgBtn('拒绝变更','cgRejectChange()','danger',!cgHuman||cgLocked,cgAuthHint||'请先撤回在途确认请求；终态不能再拒绝')}</div><div class="note danger">转为新版本需重新认证。撤回会使原确认请求失效；转为新版本会应用标准差异与工作项影响，并同事务调整已获同意的容差基线（基线版本 +1）；拒绝将告知甲方理由，保持原需求。</div>${cgChange.state==='accepted'?`<p class="note ok">已接受（需求 v${cgChange.version}） · ${cgEsc(cgChange.notice||'已向甲方告知结果与影响。')}</p>`:''}</div>`)}</div>`;
};
function cgSetPrice(cgInput){const cgChange=cgChanges[cgCurrent];if(!cgAllowed()||cgChange.state!=='evaluating')return route();if(!cgInput.checkValidity()||(cgInput.value!==''&&!Number.isFinite(Number(cgInput.value)))){cgInput.reportValidity();return;}if(cgInput.value!==cgChange.price){cgChange.price=cgInput.value;cgChange.revision++;cgChange.approval=null;toast('费用已更新；旧版确认失效，需重新提交确认');route();}}
function cgSubmitApproval(){const cgChange=cgChanges[cgCurrent];if(!cgAllowed()||!cgReady(cgChange)||!cgChange.breached||cgChange.state!=='evaluating'||cgChange.approval||cgChange.base!==cgOriginal.version)return toast('当前条件不允许提交确认');cgChange.state='waiting';route();toast('已向甲方提交同版影响确认（浏览器内演示）');}
function cgDanger(cgTitle,cgConsequence,cgCall){openModal(`<div class="stack" style="padding:24px"><h3>${cgTitle}</h3><div class="note danger">${cgConsequence}需重新认证；原型仅演示流程，不验证真实身份。</div><label class="row"><input id="cgReauth" type="checkbox" onchange="document.getElementById('cgDangerConfirm').disabled=!this.checked">我理解后果并演示重新认证</label><div class="row">${cgBtn('取消','closeModal()')}<button id="cgDangerConfirm" class="btn danger" disabled onclick="${cgEsc(cgCall)}">确认并继续</button></div></div>`);}
function cgTeamDanger(cgAction){const cgChange=cgChanges[cgCurrent];if(!cgAllowed()||(cgAction==='convert'?!cgCanConvert(cgChange):cgChange.state!=='waiting'))return toast('当前条件不允许此操作');if(cgAction!=='convert')return cgApplyTeam(cgAction);cgDanger(cgAction==='convert'?'转为需求 v'+(cgChange.base+1):'撤回确认请求',cgAction==='convert'?'应用标准差异与工作项影响；已获同意的容差基线在同事务调整，保留历史。':'甲方原确认入口将失效，需求保持原版本。',`cgApplyTeam('${cgAction}')`);}
function cgApplyTeam(cgAction){const cgChange=cgChanges[cgCurrent];if((cgAction==='convert'&&!document.getElementById('cgReauth')?.checked)||!cgAllowed())return toast('请重新认证');if(cgAction==='withdraw'){if(cgChange.state!=='waiting')return toast('请求已失效');cgChange.state='evaluating';cgChange.approval=null;}else{if(!cgCanConvert(cgChange))return toast('转换条件已失效');cgOriginal.version++;cgOriginal.expected=cgChange.expected;cgChange.version=cgOriginal.version;cgChange.state='accepted';cgOriginal.history.push([cgOriginal.version,`${cgChange.title}；来自 ${cgChange.id}`]);cgChange.notice=`变更已接受；工期 +${cgChange.days} 天，新的预计日期 ${cgChange.expected}；${cgPrice(cgChange)}。${cgChange.breached?'按你确认的方案执行。':'容差内，无需你确认。'}`;}closeModal();route();toast(cgAction==='withdraw'?'确认请求已撤回':'已创建新需求版本并告知甲方（浏览器内演示）');}
function cgOffline(){const cgChange=cgChanges[cgCurrent];if(!cgAllowed()||cgChange.state!=='waiting')return toast('当前不能登记线下同意');openModal(`<form class="stack" style="padding:24px" onsubmit="cgSaveOffline(event)"><h3>记录线下同意 · 由团队记录</h3><div class="note info">必须上传甲方对当前工期与费用的书面同意证据；记录对应当前评估修订，不自动转换需求。</div><label class="stack">书面证据（必填）<input name="evidence" type="file" required multiple onchange="cgFileLimit(this)"></label><label class="row"><input name="confirmed" type="checkbox" required>我已核对证据覆盖当前工期与费用</label><div class="row"><button type="submit" class="btn primary">记录同意</button>${cgBtn('取消','closeModal()')}</div></form>`);}
function cgSaveOffline(cgEvent){cgEvent.preventDefault();const cgForm=cgEvent.target,cgChange=cgChanges[cgCurrent];if(!cgAllowed()||cgChange.state!=='waiting'||!cgForm.elements.confirmed.checked||!cgForm.elements.evidence.files.length||cgForm.elements.evidence.files.length>10)return toast('请上传书面证据并确认覆盖当前影响');cgSaveDecision(cgChange,'approved','','offline',Array.from(cgForm.elements.evidence.files,cgFile=>cgFile.name));}
function cgRejectChange(){const cgChange=cgChanges[cgCurrent];if(!cgAllowed()||cgChange.state!=='evaluating')return toast('当前不能拒绝变更');openModal(`<form class="stack" style="padding:24px" onsubmit="cgSaveReject(event)"><h3>拒绝变更</h3><label class="stack">给甲方的话（必填）<textarea name="message" required style="${cgStyle}" rows="4"></textarea></label><div class="note warn">拒绝后告知甲方理由，原需求保持不变。</div><div class="row"><button type="submit" class="btn danger">确认拒绝</button>${cgBtn('取消','closeModal()')}</div></form>`);}
function cgSaveReject(cgEvent){cgEvent.preventDefault();const cgForm=cgEvent.target,cgChange=cgChanges[cgCurrent],cgMessage=cgForm.elements.message.value.trim();if(!cgAllowed()||cgChange.state!=='evaluating'||!cgMessage)return toast('请填写给甲方的话');cgChange.reason=cgMessage;cgChange.state='declined';closeModal();route();toast('已拒绝并向甲方告知理由（浏览器内演示）');}
